#!/usr/bin/env bash
# 소스 스크립트를 하나로 합치고, 구형 휴대폰 브라우저도 읽을 수 있는 문법(ES2017)으로 변환한다.
# 결과: dist/game.js, dist/style.css  (index.html 은 이 두 파일만 불러온다)
# 사용법: bash tools/build.sh
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p dist
SRC=(js/data.js js/data_classes.js js/class_elem.js js/class_fire.js js/prologue.js js/pro_arcs_a.js js/pro_arcs_b.js js/pro_arcs_c.js js/pro_hooks.js js/pro_life.js js/game.js js/world.js js/society.js js/story.js js/story_events.js js/story_chains.js js/situation.js js/combat.js js/fx.js assets/portraits/portraits.js js/portrait.js js/mapview.js js/portrait_parts.js js/ui.js js/ui_town.js js/merc.js js/crew.js js/gate_explore.js js/ui_prologue.js js/pro_variety.js js/dialogue.js js/voice_reg.js js/tutorial.js js/status_check.js js/hunter.js js/debut.js js/gate_run.js js/formation.js js/ui_mobile.js js/balance.js js/ascend.js js/story_clues.js js/explore.js js/story_calendar.js js/life.js js/gate_eco.js js/travel.js js/news.js js/map_parties.js js/curse.js js/npc_ai.js js/npc_memory.js js/sfx.js js/forge.js js/affiliation.js js/pro_eve.js js/factions.js js/calamity.js js/fx_feel.js js/conspiracy.js js/hidden.js js/soul.js js/bond.js js/north.js js/gossip.js js/origin.js js/pacing.js js/bond_more.js js/orders.js js/rift.js js/archetypes.js js/hideout.js js/story_roles.js js/lifeskill.js js/world_first.js js/named.js js/bonds.js js/story_regions.js js/public_order.js js/ui_sheet.js js/life_end.js js/contract.js js/gear.js js/own_guild.js js/onboarding.js js/gear2.js js/gear3.js js/civil.js js/business.js js/tutorial_map.js js/combat_fit.js js/council.js js/gate_watch.js js/explore_view.js js/tut_lock.js js/elem_hint.js js/recall_drop.js js/eco_recall.js js/intent.js js/elem6.js js/tactics.js js/persona.js js/persona_council.js js/mvp.js js/class_elem_npc.js js/break_gauge.js js/boss_pattern.js js/raid.js js/status_fx.js js/combo_skill.js js/monster_pack.js js/limit_gauge.js js/party_bonus.js js/idcard.js js/elem_react.js js/bestiary.js js/battle_intro.js js/train_spots.js js/hud_b.js js/info_btn.js js/settle_pop.js js/fx3d_loader.js js/hunternet.js js/minor_guilds.js js/check.js js/bond_pace.js js/mon_size.js js/skill_hold.js js/aoe_burst.js js/aff_flow.js js/payroll.js js/resume_guard.js js/pace_high.js js/eval_ui.js js/eval_game.js js/late_econ.js js/solo_relief.js js/bond_vary.js js/gate_scout.js js/bond_alt_lines.js js/assassin_trait.js js/gate_tender.js js/affil_risk.js js/boss_poach.js js/gate_pursuit.js js/gate_owner.js js/duel_after.js js/duel_after_ui.js js/gate_loss.js js/gate_parties.js js/gate_parties_view.js js/duel_witness.js js/council_exam.js js/tut_pause.js js/first_team.js js/hud_money.js js/buff_fx.js js/ally_card.js js/persona_greet.js js/speech.js js/unit_hold.js js/spawn_fx.js js/battle_layout.js js/leader_rule.js js/crew_time.js js/main_story.js js/main_part1.js js/main_part2.js js/main_part3.js js/main_part4.js js/main_part5.js js/main_part6.js js/main_ending.js js/main_log.js js/rally_pay.js js/team_info.js js/guild_parties.js js/guild_roster.js js/rank_file.js js/antitrust.js js/world_scale.js js/explore_cutscene.js js/prologue_cutscene.js js/explore_onescreen.js js/leader_explore.js js/transport.js js/own_vehicle.js js/persona_voice.js js/map_terrain.js js/guild_towns.js js/monster_art_data.js js/item_art_data.js js/skill_art_data.js js/monster_art.js js/monster_world.js js/tut_skip.js js/settle_sheet.js js/wallet_chip.js js/transport_econ.js js/no_autofollow.js js/loot_split.js js/item_pop.js js/item_art.js js/skill_art.js js/hud_date.js js/hud_pc_layout.js js/map_hover_info.js js/map_face_markers.js js/map_move_confirm.js js/loot_gain_ui.js js/council_dlg.js js/wardrobe.js js/job_outfits.js js/world_opening.js js/esc_close.js js/portrait_lift.js js/recon_vision.js js/skill_grow.js js/skill_ext_base.js js/skill_ext_1.js js/skill_ext_2.js js/skill_ext_3.js js/skill_ext_4.js js/skill_ext_5.js js/skill_ext.js js/skill_gods.js js/main_cast_art.js)
cat "${SRC[@]}" > dist/game.src.js
ESBUILD="npx --yes esbuild@0.24.0"
$ESBUILD dist/game.src.js --minify --target=es2017,chrome61,safari11 --charset=utf8 --log-level=warning --outfile=dist/game.js
# three.js 스킬 이펙트는 따로 묶어 늦게 불러온다 (js/fx3d_loader.js, 4-15)
FX3D_SRC=(vendor/three_fx.js js/fx3d.js)
cat "${FX3D_SRC[@]}" > dist/fx3d.src.js
$ESBUILD dist/fx3d.src.js --minify --target=es2017,chrome61,safari11 --charset=utf8 --log-level=warning --outfile=dist/fx3d.js
cat css/style.css css/ui_b.css css/dialogue.css css/explore_view.css css/combat_ab.css css/combat_ac.css css/check.css css/eval_fix.css css/explore_cutscene.css css/prologue_cutscene.css css/explore_onescreen.css css/transport.css css/monster_art.css css/item_art.css css/skill_art.css css/world_opening.css > dist/style.src.css
$ESBUILD dist/style.src.css --target=chrome61,safari11 --charset=utf8 --log-level=warning --outfile=dist/style.css
rm dist/game.src.js dist/style.src.css dist/fx3d.src.js
echo "built dist/game.js ($(wc -c < dist/game.js) bytes), dist/fx3d.js ($(wc -c < dist/fx3d.js) bytes), dist/style.css ($(wc -c < dist/style.css) bytes)"
